const $=s=>document.querySelector(s),KEY='lived-history-v1';
let raw=null;
try{raw=JSON.parse(localStorage.getItem(KEY))}catch{}
let state=migrateSave(raw),screen='home',studyTab='review',quizMode='story',reviewQuestionId=null,reviewAnswer=null,modal=null;
const statNames={health:'체력',knowledge:'지식',fame:'명성',wealth:'재산'};
const relationNames={doyun:'도윤',village:'마을 주민',merchant:'상단',royal:'왕건 세력'};
const run=()=>state.run,meta=()=>state.meta;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const progress=()=>run().completed?100:Math.min(96,Math.round(run().visited.length/Object.keys(STORIES).length*100));
const currentCorrect=()=>Object.values(run().questionResults).filter(Boolean).length;
const cumulativeAccuracy=()=>{const records=Object.values(meta().questionRecords),attempts=records.reduce((n,r)=>n+r.attempts,0),correct=records.reduce((n,r)=>n+r.correctCount,0);return attempts?Math.round(correct/attempts*100):0};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('저장 공간을 사용할 수 없습니다. 브라우저 설정을 확인해 주세요.')}}
function toast(t){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),2600)}

function icon(name){const paths={home:'<path d="M3 10.5 10 4l7 6.5v7H6v-7"/>',era:'<circle cx="10" cy="10" r="7"/><path d="M10 3v14M3 10h14"/>',study:'<path d="M4 4h5a2 2 0 0 1 2 2v11a2 2 0 0 0-2-2H4zM16 4h-3a2 2 0 0 0-2 2v11a2 2 0 0 1 2-2h3z"/>',records:'<path d="M4 17V9m6 8V3m6 14v-5"/>',lock:'<rect x="5" y="9" width="10" height="8" rx="2"/><path d="M7 9V7a3 3 0 0 1 6 0v2"/>'};return `<svg class="icon" viewBox="0 0 20 20" aria-hidden="true">${paths[name]||paths.home}</svg>`}
function shell(content){const tab=['game','quiz','complete','teaser','history'].includes(screen)?'home':screen;return `<div class="shell"><aside class="sidebar"><div class="brand">살아본 한국사<small>HISTORY, LIVED.</small></div><nav class="nav" aria-label="주 메뉴">${[['home','홈'],['era','시대'],['study','공부'],['records','내 기록']].map(([id,label])=>`<button data-nav="${id}" class="${tab===id?'active':''}">${icon(id)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-foot"><b>역사 속, 나의 이야기</b>외우는 역사에서<br>살아보는 역사로.<br><span>CHAPTER 01 · GORYEO</span></div></aside><main class="main fade">${content}</main></div>${modal?modalHTML():''}`}
function pageHeader(title,sub='YOUR HISTORY, YOUR STORY'){return `<header class="topbar"><div><div class="eyebrow">${sub}</div><h1>${title}</h1></div><div class="toptools"><span>나의 첫 번째 역사 여행</span><button class="avatar" data-action="status" aria-label="내 상태 보기">나</button></div></header>`}
function assetStyle(assetId){const a=ASSETS[assetId]||ASSETS['home-goryeo'];return a.src?`background-image:url('${a.src}')`:`--scene-a:${a.palette?.[0]||'#263640'};--scene-b:${a.palette?.[1]||'#8b6d4b'}`}
function assetNotice(assetId,compact=false){const a=ASSETS[assetId]||ASSETS['home-goryeo'];if(a.status!=='ASSET_REQUIRED')return '';return `<div class="asset-required ${compact?'compact':''}"><span>ASSET_REQUIRED</span><b>${esc(assetId)}</b><small>${esc(a.label)}</small></div>`}

function home(){const r=run(),hasSave=r.started;return pageHeader('오늘은 어떤 역사를 살아볼까요?')+`<section class="hero"><div class="hero-content"><span class="pill">EPISODE 01 · 918 — 1392</span><h2><span>눈떠보니</span>고려</h2><p>눈을 뜨니, 교과서 속 세상이다.<br>새로운 나라의 시작에서 나의 이야기가 시작된다.</p><div class="hero-bottom"><button class="primary" data-action="play">${hasSave?'이야기 이어하기':'이야기 시작하기'}</button>${hasSave?'<button class="secondary" data-action="restart">처음부터 다시하기</button>':''}<small>CH.01 &nbsp; 918년, 새로운 나라</small></div></div><span class="hero-mark">당신의 선택이 역사가 되는 순간</span></section><div class="home-grid"><section><div class="section-title"><h2>나의 고려 이야기</h2><button class="text-btn" data-nav="records">기록 보기 &nbsp; ›</button></div><div class="chapter-line"><img class="chapter-thumb" src="goryeo.png" alt="고려 시대 전경"><div class="chapter-copy"><small>CHAPTER 01</small><h3>918년, 새로운 나라</h3><p>${hasSave?`${r.job==='없음'?'낯선 이':esc(r.job)} · ${r.visited.length}개의 장면을 경험했어요`:'아직 쓰이지 않은, 당신의 첫 번째 이야기'}</p><div class="progress"><span style="width:${progress()}%"></span></div></div><span class="badge">${r.completed?'완료':hasSave?progress()+'%':'시작 가능'}</span></div><div class="section-title home-understanding"><h2>시대별 이해도</h2><span class="text-btn">차근차근, 역사를 내 것으로</span></div><div class="era-strip">${ERAS.map(([name],i)=>`<div class="era-item"><b>${name}</b><small>${i===0?cumulativeAccuracy():0}%</small><div class="progress"><span style="width:${i===0?cumulativeAccuracy():0}%"></span></div></div>`).join('')}</div></section><aside class="review"><span class="eyebrow">${meta().wrongQuestionIds.length?'TODAY’S REVIEW':'A MOMENT TO REMEMBER'}</span><h3>${meta().wrongQuestionIds.length?'다시 만나면,<br>더 오래 기억하니까.':'살아본 순간이,<br>나의 지식이 되도록.'}</h3><p>${meta().wrongQuestionIds.length?`복습할 역사 ${meta().wrongQuestionIds.filter(id=>!meta().reviewedQuestionIds.includes(id)).length}개가 기다리고 있어요.`:'이야기에서 경험한 사건이<br>시험 문제와 자연스럽게 이어집니다.'}</p><button data-nav="study">${meta().wrongQuestionIds.length?'오늘의 복습 시작':'나의 학습 기록'}</button></aside></div><footer class="bottom-note"><span>선택하고, 살아보고, 기억하는 한국사.</span><span>진행 상황은 이 기기에 자동 저장됩니다.</span></footer>`}
function eras(){return pageHeader('당신이 살아갈 시대','CHOOSE YOUR ERA')+`<p class="lead">한 시대의 시작에서, 나만의 이야기를 만나세요.</p><div class="era-list">${ERAS.map(([name,years],i)=>`<section class="era-card"><span class="eyebrow">EPISODE 0${i+1}</span><h2>눈떠보니 ${name}</h2><p>${years}</p>${i===0?`<div class="era-actions"><button class="primary" data-action="play">${run().started?'이야기 이어하기':'이야기 시작하기'}</button>${run().started?'<button class="secondary" data-action="restart">처음부터 다시하기</button>':''}</div>`:`<span class="badge">${icon('lock')} &nbsp; COMING SOON</span>`}</section>`).join('')}</div>`}
function enterStory(){const r=run(),id=r.storyId,dialogueKey=r.pending?`result:${r.pending.sourceSceneId}`:id;if(r.dialogueSceneId!==dialogueKey){r.dialogueSceneId=dialogueKey;r.dialogueCursor=1}if(STORIES[id]&&!r.visited.includes(id))r.visited.push(id);const add=(list,value)=>{if(!list.includes(value))list.push(value)};if(id==='village')add(meta().achievements,'time-traveler');if(id==='rumor')add(meta().people,'왕건');if(id==='foundation'){add(meta().historicalEvents,'goryeo-foundation-918');add(meta().cards,'goryeo-foundation-918')}if(id==='market'||id==='doyun'){add(meta().people,'궁예');add(meta().people,'견훤')}save()}
function memoryNote(sceneId){if(sceneId==='foundation'){if(run().initialMemory==='918')return '<div class="memory-note correct-memory">당신의 기억이 맞았습니다. · 918년 고려 건국</div>';if(run().initialMemory==='936')return '<div class="memory-note">918년과 936년을 헷갈리고 있어요. 936년의 의미는 곧 다시 만나게 됩니다.</div>';return '<div class="memory-note">방금 경험한 장면이 새로운 기억이 되었습니다. · 918년 고려 건국</div>'}return ''}
function statusSnapshot(sceneId){if(sceneId!=='status')return '';const r=run();return `<div class="first-status"><span><small>신분</small>${r.status}</span><span><small>직업</small>${r.job}</span><span><small>재산</small>${r.stats.wealth}냥</span><span><small>명성</small>${r.stats.fame}</span><span><small>체력</small>${r.stats.health}</span><span><small>지식</small>${r.stats.knowledge}</span></div>`}
function resultChips(p){const stats=Object.entries(p.statChanges||{}).filter(([,v])=>v!==0).map(([k,v])=>`<span>${statNames[k]} ${v>0?'+':''}${v}${k==='wealth'?'냥':''}</span>`);const relations=Object.entries(p.relationshipChanges||{}).filter(([,v])=>v!==0).map(([k,v])=>`<span>${relationNames[k]} ${v>0?'+':''}${v}</span>`);if(p.job&&p.job!=='없음')stats.push(`<span>새 직업 · ${esc(p.job)}</span>`);return [...stats,...relations].join('')}
function conversationEntries(source,p){if(p)return p.resultDialogues?.length?p.resultDialogues:[dialogueLine('player','serious',p.label),dialogueLine('narrator','neutral',p.result,'narration')];return source.dialogues?.length?source.dialogues:[dialogueLine('narrator','neutral',source.dialogue,'narration')]}
function portraitCard(entry){if(!entry.portrait)return '';const asset=PORTRAITS[entry.portrait]||{status:'ASSET_REQUIRED',label:`${entry.characterName} ${entry.expression}`,palette:['#263a45','#81684e']};if(asset.src)return `<img class="character-portrait" src="${esc(asset.src)}" alt="${esc(entry.characterName)} ${esc(entry.expression)} 표정">`;return `<div class="character-portrait portrait-placeholder" data-portrait="${esc(entry.portrait)}" style="--portrait-a:${asset.palette?.[0]||'#263a45'};--portrait-b:${asset.palette?.[1]||'#81684e'}"><span>ASSET_REQUIRED</span><b>${esc(entry.portrait)}</b><small>${esc(entry.expression)}</small></div>`}
function dialogueBubble(entry,index){if(entry.speakerType==='thought')return `<div class="monologue" data-dialogue-index="${index}" data-speaker-type="thought"><span>속마음</span><p>${esc(entry.dialogue)}</p></div>`;if(entry.speakerType==='narration')return `<div class="narration-line" data-dialogue-index="${index}" data-speaker-type="narration"><p>${esc(entry.dialogue)}</p></div>`;const side=entry.speakerType==='player'?'player':'npc',portrait=portraitCard(entry),content=`<div class="bubble-stack"><span class="character-name">${esc(entry.characterName)}</span><p class="speech-bubble">${esc(entry.dialogue)}</p></div>`;return `<div class="message-row ${side}" data-dialogue-index="${index}" data-speaker-type="${side}" data-expression="${esc(entry.expression)}">${side==='npc'?portrait+content:content+portrait}</div>`}
function choiceButtons(source,r){return `<div class="choice-dock"><span>나의 선택</span><div class="choices">${source.choices.map((c,i)=>{const available=choiceAvailable(r,c);return `<button class="choice ${available?'':'locked-choice'}" data-choice="${i}" ${available?'':'disabled'}><span>${esc(c.label)}</span>${c.hint?`<small>${available?'':icon('lock')+' '}${esc(c.hint)}</small>`:''}</button>`}).join('')}</div></div>`}
function game(){const r=run(),s=STORIES[r.storyId],p=r.pending;if(!s&&!p)return home();const source=p?STORIES[p.sourceSceneId]:s,assetId=p?p.resultIllustrationId:source.illustrationId,entries=conversationEntries(source,p),cursor=Math.max(1,Math.min(r.dialogueCursor||1,entries.length)),complete=cursor>=entries.length,visibleCount=complete&&source.choices&&!p?2:3,visibleStart=Math.max(0,cursor-visibleCount),visible=entries.slice(visibleStart,cursor);return `<section class="game conversation-game ${ASSETS[assetId]?.src?'has-art':'needs-art'}" style="${assetStyle(assetId)}">${assetNotice(assetId)}<div class="game-header"><button class="glass" data-nav="home">‹ &nbsp; 이야기 나가기</button><span class="glass">CH.01 &nbsp; ${source.year}년</span><button class="glass" data-action="status">내 상태</button></div><div class="game-stats"><span>♡ &nbsp; 체력 ${r.stats.health}</span><span>◇ &nbsp; 지식 ${r.stats.knowledge}</span><span>◉ &nbsp; ${r.stats.wealth}냥</span></div><div class="scene-title"><small>${esc(source.location)}</small><h2>${p?'내 선택으로 달라진 장면':esc(source.title)}</h2></div><section class="conversation-panel" aria-label="대화"><div class="dialogue-log">${visible.map((entry,i)=>dialogueBubble(entry,visibleStart+i)).join('')}</div><div class="dialogue-step"><span>${cursor} / ${entries.length}</span>${!complete?'<button class="advance-dialogue" data-action="advance-dialogue">탭하여 계속 <b>›</b></button>':''}</div>${complete&&!p?memoryNote(source.sceneId)+statusSnapshot(source.sceneId):''}${complete?(p?`<div class="result-chips">${resultChips(p)}</div><button class="primary next" data-action="result-next">이야기 계속</button>`:source.choices?choiceButtons(source,r):`<button class="primary next" data-action="next">${source.quizId?'🧠 기억을 더듬는다':source.nextStoryId==='voice'?'잠이 든다':'다음 이야기'}</button>`):''}<div class="conversation-sub">${p?'선택 → 대사 → 반응 → 결과가 저장됩니다.':'최근 대화만 남겨 장면에 집중할 수 있어요.'}</div></section><div class="chapter-progress">${Array.from({length:24},(_,i)=>`<i class="${progress()>i/24*100?'on':''}"></i>`).join('')}</div></section>`}

function activeQuestion(){return QUESTIONS.find(q=>q.questionId===(quizMode==='story'?run().activeQuestionId:reviewQuestionId))}
function quiz(){const q=activeQuestion();if(!q)return study();const selected=quizMode==='story'?run().questionAnswer:reviewAnswer,done=selected!==null,correct=done&&selected===q.answer,asset=ASSETS[q.relatedIllustrationId];return pageHeader(quizMode==='story'?'방금 경험한 역사, 시험에서는?':'틀린 장면 다시 보기','REMEMBER THE MOMENT')+`<section class="quiz"><div class="story-test-head"><span class="badge">${q.questionId==='ch01-boss'?'BOSS QUESTION':'STORY TEST'} · ${q.difficulty}</span><span>${esc(q.questionType)}</span></div><div class="quiz-memory ${asset?.src?'has-art':'needs-art'}" style="${assetStyle(q.relatedIllustrationId)}">${assetNotice(q.relatedIllustrationId,true)}<div><small>이 장면 기억나요?</small><b>${esc(asset?.label)}</b></div></div><div class="memory-trigger">🧠 ${q.questionId==='ch01-test-01'?'기억을 더듬는다':'방금 들은 이야기가 익숙하다.'}</div>${q.passage?`<div class="passage">${esc(q.passage)}</div>`:''}<h2>${esc(q.question)}</h2><span class="text-btn">자체 제작 기출형 문제 · 공식 기출문제가 아닙니다</span>${q.choices.map((x,i)=>`<button class="choice ${done&&i===q.answer?'correct':done&&i===selected?'wrong':''}" data-answer="${i}" ${done?'disabled':''}><span>${['①','②','③','④','⑤'][i]} &nbsp; ${esc(x)}</span>${done&&i===q.answer?'✓':''}</button>`).join('')}${done?`<div class="feedback" role="status"><h3>${correct?'기억이 선명해졌다.':'기억이 흐릿하다.'}</h3><p>${esc(q.explanation)}</p><div class="keywords">${q.examKeywords.map(x=>`<span>${esc(x)}</span>`).join('')}</div><p class="feedback-reward">${correct?`정답 · 지식 +${q.rewardKnowledge||2}`:'오답노트 +1 · 이야기는 계속됩니다.'}</p></div><button class="primary next" data-action="quiz-next">${quizMode==='review'?'오답노트로 돌아가기':q.resumeStoryId==='complete'?'CHAPTER 결과 보기':'다시 이야기로 돌아가기'}</button>`:''}</section>`}

function study(){let body='';if(studyTab==='review'){body=meta().wrongQuestionIds.length?meta().wrongQuestionIds.map(id=>{const q=QUESTIONS.find(x=>x.questionId===id);if(!q)return '';return `<div class="list-row"><div><span class="badge">${meta().reviewedQuestionIds.includes(id)?'복습 완료':'복습 필요'}</span><h3>${esc(q.question.split('\n')[0])}</h3><p>${q.examKeywords.slice(0,3).map(esc).join(' · ')}</p></div><button class="primary" data-review="${q.questionId}">다시 풀기</button></div>`}).join(''):`<div class="empty">아직 틀린 역사가 없어요.<br><small>스토리 중간 문제를 풀면 복습할 내용이 이곳에 모여요.</small></div>`}if(studyTab==='quiz')body=QUESTIONS.map((q,i)=>`<div class="list-row"><div><span class="eyebrow">${q.questionId==='ch01-boss'?'BOSS QUESTION':`STORY TEST 0${i+1}`}</span><h3>${esc(q.question.split('\n')[0])}</h3><p>${esc(q.questionType)} · ${esc(q.difficulty)} · ${meta().questionRecords[q.questionId]?(meta().questionRecords[q.questionId].lastCorrect?'최근 정답':'다시 기억하기'):'아직 만나지 못했어요'}</p></div><button class="primary" data-practice="${q.questionId}">문제 풀기</button></div>`).join('');if(studyTab==='timeline')body=[['900','견훤, 후백제 건국','완산주를 중심으로 후백제를 세웠습니다.'],['901','궁예, 후고구려 건국','이후 국호를 마진, 태봉으로 바꾸었습니다.'],['918','고려 건국','왕건이 신하들의 추대를 받아 왕위에 올랐습니다.'],['935','신라의 항복','경순왕이 고려에 항복했습니다.'],['936','후삼국 통일','고려가 후백제를 무너뜨리고 통일했습니다.']].map(([y,t,d])=>`<div class="list-row timeline-row"><div><span class="eyebrow">${y}년</span><h3>${t}</h3><p>${d}</p></div></div>`).join('');if(studyTab==='cards')body=`<div class="collection">${['고려 건국','왕건','궁예','견훤','광종','노비안검법'].map((x,i)=>{const unlocked=i===0?meta().cards.length>0:meta().people.includes(x);return `<div class="collect ${unlocked?'':'locked'}">${icon(unlocked?'study':'lock')}<h3>${unlocked?x:'아직 만나지 못한 역사'}</h3><p>${unlocked?'CH.01에서 직접 만난 역사':'이야기를 진행하면 열립니다'}</p>${unlocked&&i===0?'<button class="text-btn" data-nav="history">자세히 보기 ›</button>':''}</div>`}).join('')}</div>`;return pageHeader('살아본 순간을, 오래 기억하도록','MY STUDY')+`<div class="tabs">${[['review','오답노트'],['quiz','시험 문제'],['timeline','역사 연표'],['cards','역사 도감']].map(([id,x])=>`<button data-study="${id}" class="${studyTab===id?'selected':''}">${x}</button>`).join('')}</div>${body}`}
function history(){return pageHeader('방금, 당신이 경험한 역사','HISTORY DISCOVERED')+`<article class="history-card"><span class="eyebrow">역사 카드 001 · 고려</span><h2>918년<br>${HISTORY.title}</h2><img src="goryeo.png" alt="고려 시대 전경"><p>${HISTORY.summary}</p><div class="info-note">주인공과 도윤의 이야기는 창작입니다. 문제도 공식 기출을 복제하지 않은 자체 제작 문항입니다.</div><h3>시험에서는 이렇게 기억하세요</h3><div class="keywords">${HISTORY.examKeywords.map(x=>`<span>${x}</span>`).join('')}</div><p class="source-link"><a href="https://contents.history.go.kr/mobile/kc/view.do?code=kc_age_10&levelId=kc_i101800" target="_blank" rel="noopener noreferrer">역사 내용 참고 · 국사편찬위원회 우리역사넷</a></p></article>`}
function records(){const records=Object.values(meta().questionRecords),attempts=records.reduce((n,r)=>n+r.attempts,0);return pageHeader('한 걸음씩, 나의 한국사','MY JOURNEY')+`<div class="stats-grid">${[['현재 스토리 진행률',progress()+'%'],['누적 문제 정답률',attempts?cumulativeAccuracy()+'%':'—'],['풀어본 문제',Object.keys(meta().questionRecords).length+' / 6'],['오답 기록',meta().wrongQuestionIds.length+'개'],['발견한 역사 사건',meta().historicalEvents.length],['완료한 삶',meta().completedRuns+'회']].map(([t,v])=>`<div class="stat-box"><small>${t}</small><strong>${v}</strong></div>`).join('')}</div><div class="section-title"><h2>현재 고려 인생</h2><button class="text-btn" data-action="status">상태창 보기 ›</button></div><div class="list-row"><div><h3>${run().status} · ${esc(run().job)}</h3><p>918년 · ${esc(run().route||'아직 정하지 않음')} · 최고 재산 ${run().peakWealth}냥</p></div><span class="badge">${run().completed?'첫 장을 마쳤어요':run().started?'이야기 진행 중':'시작 전'}</span></div><div class="list-row"><div><h3>누적 수집 기록</h3><p>인물 ${meta().people.length}명 · 카드 ${meta().cards.length}장 · 엔딩 ${meta().endings.length}개 · 업적 ${meta().achievements.length}개</p></div></div><div class="list-row"><div><h3>이번 회차 선택 ${run().choices.length}개</h3><p>${run().choices.length?run().choices.slice(-3).map(c=>esc(c.label)).join(' · '):'아직 선택한 이야기가 없습니다.'}</p></div></div>${run().completed?'<button class="primary next" data-nav="complete">나의 챕터 결과 보기</button>':''}${run().started?'<button class="text-btn restart-link" data-action="restart">처음부터 다시하기</button>':''}`}
function complete(){const r=run(),correct=currentCorrect(),missed=QUESTIONS.length-correct,confused=r.initialMemory==='936'?'918년 ↔ 936년':missed?'후삼국 사건의 순서와 인물 연결':'없음';return `<section class="complete"><div class="seal">史</div><div class="eyebrow complete-label">CHAPTER 01 COMPLETE</div><h1>새로운 나라</h1><p>${r.route==='merchant'?'상단에서 일하며 고려의 첫날을 살아냈습니다.':r.route==='village'?'마을 사람들과 함께 고려의 첫날을 살아냈습니다.':r.route==='royal'?'왕건을 향한 특별한 뜻을 품고 고려의 첫날을 살아냈습니다.':'도윤과 송악으로 향하며 고려의 첫날을 살아냈습니다.'}</p><div class="history-flow"><span>견훤<br><b>후백제</b></span><i>→</i><span>궁예<br><b>후고구려</b></span><i>→</i><span>왕건<br><b>918 고려</b></span><i>→</i><span>935 신라 항복<br><b>936 통일</b></span></div>${r.initialMemory==='936'?'<div class="memory-note">처음에 헷갈렸던 936년은 후삼국 통일의 해였습니다.</div>':''}<h2 class="result-title">나의 첫 번째 고려 생활</h2><div class="stats-grid">${[['선택한 삶',r.job],['재산',r.stats.wealth+'냥'],['명성',r.stats.fame],['지식',r.stats.knowledge],['도윤 관계',r.relations.doyun],['경험한 사건','고려 건국']].map(([t,v])=>`<div class="stat-box"><small>${t}</small><strong>${v}</strong></div>`).join('')}</div><div class="chapter-learning"><div><small>CH.01 문제</small><strong>${correct} / 6 정답</strong></div><div><small>정답률</small><strong>${Math.round(correct/6*100)}%</strong></div><div><small>헷갈리는 개념</small><strong>${confused}</strong></div><div><small>오답</small><strong>${missed}개</strong></div></div>${missed?'<button class="secondary full" data-action="review-wrong">틀린 문제 다시 풀기</button>':''}<button class="primary next" data-nav="teaser">다음 이야기 미리 보기</button><button class="secondary full" data-action="restart">다른 선택으로 다시 살아보기</button><button class="text-btn home-link" data-nav="home">홈으로 돌아가기</button></section>`}
function teaser(){return `<section class="hero teaser needs-art" style="${assetStyle('chapter-02-teaser')}">${assetNotice('chapter-02-teaser')}<div class="hero-content teaser-content"><span class="pill">CHAPTER 02 · COMING SOON</span><h2>왕의 나라</h2><p>관리들이 문서를 조사한다.<br>“본래 양인이었던 자를 노비로 삼은 기록이 있군.”<br>“폐하의 명이다. 모두 다시 조사한다.”<br><br><b>광종</b></p><button class="primary teaser-button" data-nav="home">나의 이야기로 돌아가기</button></div></section>`}
function modalHTML(){if(modal==='restart')return `<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="CH.01 다시 시작"><h2>CH.01을 다시 시작할까요?</h2><p class="lead modal-copy">다른 선택으로 918년의 삶을 다시 시작할 수 있어요. 현재 회차의 진행 상태는 초기화됩니다.</p><div class="modal-actions"><button class="glass" data-action="close">취소</button><button class="primary" data-action="confirm-restart">다시 시작하기</button></div><p class="data-policy">문제 풀이·오답·정답률·역사 카드·인물 도감·업적·엔딩·누적 플레이 기록은 유지됩니다.</p></section></div>`;const r=run();return `<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="내 상태"><header><h2>나의 상태</h2><button class="close" data-action="close" aria-label="닫기">×</button></header><p class="lead modal-copy">${r.status} · ${r.job}</p><div class="stats-grid">${Object.entries(r.stats).map(([k,v])=>`<div class="stat-box"><small>${statNames[k]}</small><strong>${v}${k==='wealth'?'냥':''}</strong></div>`).join('')}</div><h3>함께 살아가는 사람들</h3>${Object.entries(r.relations).map(([k,v])=>`<div class="list-row"><span>${relationNames[k]}</span><span>${v} <small>/ 100</small></span></div>`).join('')}<p class="text-btn">현재 회차 진행과 관계는 선택할 때마다 자동 저장됩니다.</p></section></div>`}
function renderContent(){return({home,era:eras,game,quiz,study,records,complete,teaser,history}[screen]||home)()}
function render(){$('#app').innerHTML=shell(renderContent());if(modal)setTimeout(()=>$('.modal button')?.focus(),0)}
function navigate(to){screen=to;modal=null;render();window.scrollTo(0,0)}
function play(){run().started=true;if(run().completed)return navigate('complete');if(run().activeQuestionId){quizMode='story';screen='quiz'}else screen='game';enterStory();render();window.scrollTo(0,0)}
function startQuestion(id){run().activeQuestionId=id;run().questionAnswer=null;quizMode='story';screen='quiz';save();render();window.scrollTo(0,0)}
function nextStory(){const s=STORIES[run().storyId];if(s?.quizId)return startQuestion(s.quizId);if(s?.nextStoryId){run().storyId=s.nextStoryId;enterStory();render()} }

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.nav)return navigate(b.dataset.nav);if(b.dataset.study){studyTab=b.dataset.study;return render()}if(b.dataset.choice!==undefined){applyChoice(state,run().storyId,Number(b.dataset.choice));save();return render()}if(b.dataset.answer!==undefined){const selected=Number(b.dataset.answer);if(quizMode==='story'){if(run().questionAnswer!==null)return;recordQuestion(state,run().activeQuestionId,selected)}else{if(reviewAnswer!==null)return;reviewAnswer=selected;recordQuestion(state,reviewQuestionId,selected);run().questionAnswer=null}save();return render()}if(b.dataset.review||b.dataset.practice){reviewQuestionId=b.dataset.review||b.dataset.practice;reviewAnswer=null;quizMode='review';return navigate('quiz')}switch(b.dataset.action){case'play':return play();case'status':modal='status';return render();case'close':modal=null;return render();case'advance-dialogue':{const r=run(),source=r.pending?STORIES[r.pending.sourceSceneId]:STORIES[r.storyId],entries=conversationEntries(source,r.pending);r.dialogueCursor=Math.min(entries.length,(r.dialogueCursor||1)+1);save();return render()}case'next':return nextStory();case'result-next':run().pending=null;enterStory();save();return render();case'quiz-next':{if(quizMode==='review'){reviewQuestionId=null;reviewAnswer=null;studyTab='review';return navigate('study')}const q=activeQuestion();if(q.resumeStoryId==='complete'){finishChapter(state);save();return navigate('complete')}run().storyId=q.resumeStoryId;run().activeQuestionId=null;run().questionAnswer=null;enterStory();save();return navigate('game')}case'restart':modal='restart';return render();case'confirm-restart':resetRun(state);modal=null;save();return play();case'review-wrong':{const first=meta().wrongQuestionIds.find(id=>run().questionResults[id]===false)||meta().wrongQuestionIds[0];if(!first)return navigate('study');reviewQuestionId=first;reviewAnswer=null;quizMode='review';return navigate('quiz')}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render()}if(e.key==='Tab'&&modal){const items=[...document.querySelectorAll('.modal button')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
if(document.modelContext){try{document.modelContext.registerTool({name:'get_history_progress',description:'Read this device’s Korean history game progress, current run, and cumulative learning record.',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify({storyId:run().storyId,completed:run().completed,stats:run().stats,accuracy:cumulativeAccuracy(),wrongAnswers:meta().wrongQuestionIds.length,completedRuns:meta().completedRuns})}]})})}catch{}}
save();render();
